// Custom Worker entry point. OpenNext's own generated `.open-next/worker.js`
// (regenerated by `opennextjs-cloudflare build` on every build — never edit
// it directly) only exports a `fetch` handler, with no hook for adding a
// `queue` consumer. So `wrangler.jsonc`'s `main` points here instead: this
// file re-exports OpenNext's fetch handler unchanged, and adds the one extra
// handler this app needs, for the stock-deduction queue.
//
// The relative import below resolves against `.open-next/worker.js`'s own
// location (standard ES module semantics), so it isn't affected by which
// file imports it, and stays valid across rebuilds.
import openNextWorker from "./.open-next/worker.js";
import { handleStockDeductionBatch } from "./src/lib/queue/stock-deduction-consumer";
import type { StockDeductionMessage } from "./src/lib/queue/stock-deduction";

export default {
  fetch: openNextWorker.fetch,
  async queue(
    batch: MessageBatch<StockDeductionMessage>,
    env: CloudflareEnv,
    _ctx: ExecutionContext
  ): Promise<void> {
    await handleStockDeductionBatch(batch, env);
  },
} satisfies ExportedHandler<CloudflareEnv, StockDeductionMessage>;

// Durable Object classes OpenNext's own worker.js re-exports (bucket cache
// purge, sharded tag cache, the ISR revalidation queue) — only used if
// wrangler.jsonc declares a durable_objects binding pointing at one of
// these class names. None are declared today, but re-exporting them here
// keeps this file a drop-in replacement if that changes later.
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
